    // Publications: publications, text with quotes.
    'publications.noPeerIsConnectedSo2': '연결된 피어가 없어서 “피어에게서 가져오기”로 누락된 콘텐츠를 가져올 수 없습니다. {peers}에서 피어에 연결하세요.',
    'publications.thisIsACorrelationOf2': '독립적으로 기록된 사실들을 명시적인 anchorId로 연결한 것입니다 — 판정이 아닙니다. 같은 anchorId에 대한 관측별 상세 내역은 위의 “Bitcoin 앵커 증거 기록”을 보세요.',
    'publications.thisIsAReadOnly': '위 파일을 읽기 전용으로 보는 것입니다 — 이 페이지 앞부분의 관측 아카이브는 전혀 바뀌지 않습니다. 이 아카이브로 교체하려면 위의 “아카이브 가져오기”를 사용하세요.',
    'publications.whatReplacingTheCurrentArchive': '현재 아카이브를 위의 외부 아카이브로 교체하면 무엇이 바뀌는지 보여 줍니다 — 아래의 “현재 아카이브 교체”를 명시적으로 클릭하기 전까지 현재 아카이브는 그대로 유지됩니다.',
    'publications.replacingRestampsEveryFactIn': '교체하면 위 외부 아카이브의 모든 사실이 IMPORTED(0.8.83)로 다시 표시됩니다 — 따라서 기반 관측이 동일하더라도 결과로 나오는 현재 지문은 위에 표시된 “외부 지문”과 다릅니다.',
    'publications.localFactsWereObservedBy': '로컬 사실은 이 복제본이 직접 관측한 것입니다. 가져온 사실은 이전의 “현재 아카이브 교체” 가져오기를 통해 이 아카이브에 들어온 것입니다. 어느 쪽도 더 신뢰할 만하지 않습니다 — 각 사실이 어디서 왔는지만 나타냅니다.',
    'publications.anExplicitDurableRecordThat2': '한 게시물이 다른 게시물을 참조한다는 명시적이고 영구적인 기록입니다 — 콘텐츠, 타임스탬프, 작성자가 일치한다고 추론하지 않습니다. 두 게시물 모두 위에서 이미 영구 식별자를 가지고 있어야 합니다. 참조는 “포크” 분류가 아니라, 이 게시물이 저 게시물을 가리킨다는 출처가 분명한 단순한 사실입니다.',
    'publications.nothingHereIsSavedAnywhere': '여기 입력한 내용은 어디에도 저장되지 않습니다. 이 설정은 이번 브라우징 세션 동안 이 페이지의 메모리에만 있으며, 페이지를 새로 고치거나 “설정 지우기”를 클릭하는 순간 사라집니다.',
    'publications.thisReplicaDoesNotCurrently': '이 복제본에는 현재 유효한 스냅샷이 없습니다. 아래에서 출처를 골라 — “스냅샷 가져오기”, 배치의 “스냅샷 구체화”, 피어의 “피어에게서 스냅샷 받기” — 다시 시도하세요.',

    // Publications: leaderboardHubView, text with quotes.
    'leaderboardHubView.aBadgePresentationOfThe': '이 게시자가 명시적으로 주장한 모든 게시물에 걸쳐 이미 얻은 업적을 배지로 표시한 것입니다 — 새로운 업적이 아니며, 점수, 순위, 리더보드 항목도 아닙니다. 일부 업적(참조에서 도출된 것)은 아직 배지 표시가 없어 위의 “게시자 업적 프로필” 카드에만 나타납니다.',

    // Publications: publisherLeaderboardSnapshotClaimAuthoringView, text with quotes.
    'publisherLeaderboardSnapshotClaimAuthoringView.authorAndExportASigned': '내 복제본의 현재 리더보드 스냅샷에 대한 서명된 클레임을 작성하고 내보냅니다 — 조정 작업 공간의 “피어 증거” 필드가 피어에게 붙여넣으라고 요청하는 바로 그 증거입니다. 생성, 서명, 내보내기는 각각 별도의 명시적 작업이며, 이 페이지의 어떤 것도 자동으로 실행되지 않습니다.',
    'publisherLeaderboardSnapshotClaimAuthoringView.pasteThisIntoAPeer': '이것을 피어의 조정 작업 공간 “피어 증거” 필드에 붙여넣거나, 다운로드한 파일을 보내세요.',

    // Publications: reconciliationCandidateLeaderboardView, text with quotes.
    'reconciliationCandidateLeaderboardView.noPeerArchiveSuppliedYet': '아직 입력한 피어 아카이브가 없습니다 — 붙여넣기 전까지 아래의 모든 개수는 원본에만 있음으로 표시됩니다. 피어 복제본이 내보낸 아카이브(게시물 페이지의 아카이브 내보내기)를 붙여넣고 “피어 아카이브로 사용”을 클릭하세요.',

    // Publications: reconciliationWorkspaceView, text with quotes.
