    'blurtSettingsView.whereThisReplicaReadsBlurt': '이 복제본이 Blurt 게시물을 읽는 곳: 사람들이 자신의 계정에서 forkbuild 태그를 단 최상위 게시물로 올리는 공개물(공유 월드, 청사진 출처 표시, 장소 이름), 스냅샷, 댓글. 게시물은 Blurt의 인덱서인 Nexus를 통해 읽으며, Nexus는 태그가 달린 게시물을 오래된 것까지 모두 보여 줍니다. Nexus가 없는 노드는 건너뜁니다. 어느 노드에도 Nexus가 없으면 태그는 게시물을 7일 뒤 보상이 지급될 때까지만 보여 주므로, 그보다 오래된 게시물은 이 기기가 게시하는 것을 본 계정의 게시 기록에서 읽습니다. 모든 공지는 사용하기 전에 검증됩니다. 읽는 데에는 Blurt 계정이 필요 없습니다. 변경 사항은 다음에 앱을 불러올 때 적용됩니다.',
